import{_ as t,o as n,c as r,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Das System der „Harten Prosa“: Macht, Geld und Nibelungentreue","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/oevp-system-finanzen.md","filePath":"recherche/oevp-system-finanzen.md"}'),a={name:"recherche/oevp-system-finanzen.md"};function s(l,e,o,d,h,g){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="das-system-der-„harten-prosa-macht-geld-und-nibelungentreue" tabindex="-1">Das System der „Harten Prosa“: Macht, Geld und Nibelungentreue <a class="header-anchor" href="#das-system-der-„harten-prosa-macht-geld-und-nibelungentreue" aria-label="Permalink to &quot;Das System der „Harten Prosa“: Macht, Geld und Nibelungentreue&quot;">​</a></h1><p>Hinter der Fassade der politischen Sacharbeit verbirgt sich in der ÖVP oft ein tief verwurzeltes System der gegenseitigen Begünstigung und der strategischen Absicherung. Wir beleuchten die Schlüsselfiguren, die das Erbe von August Wöginger antreten oder verwalten.</p><h2 id="die-akteure-und-ihre-bezuge-stand-2025-26" tabindex="-1">Die Akteure und ihre Bezüge (Stand 2025/26) <a class="header-anchor" href="#die-akteure-und-ihre-bezuge-stand-2025-26" aria-label="Permalink to &quot;Die Akteure und ihre Bezüge (Stand 2025/26)&quot;">​</a></h2><p>Hier dokumentieren wir, wie viel Steuergeld die amtierende Riege der „Systemerhalter“ pro Monat (Brutto) bezieht:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Funktion</th><th style="text-align:left;">Monatliches Brutto (ca.)</th><th style="text-align:left;">Fokus / Kontroversen</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Johanna Mikl-Leitner</strong></td><td style="text-align:left;">Landeshauptfrau NÖ</td><td style="text-align:left;"><strong>21.660 €</strong></td><td style="text-align:left;">Inseraten-Millionen, ORF-NÖ-Einflussnahme</td></tr><tr><td style="text-align:left;"><strong>Karoline Edtstadler</strong></td><td style="text-align:left;">Landeshauptfrau Salzburg</td><td style="text-align:left;"><strong>19.800 €</strong></td><td style="text-align:left;">Wechsel vom Bund (2025), strategische Kühle</td></tr><tr><td style="text-align:left;"><strong>Thomas Stelzer</strong></td><td style="text-align:left;">Landeshauptmann OÖ</td><td style="text-align:left;"><strong>19.800 €</strong></td><td style="text-align:left;">Erhöht sich 2026 das Gehalt um 3,3%</td></tr><tr><td style="text-align:left;"><strong>Gerhard Karner</strong></td><td style="text-align:left;">Innenminister</td><td style="text-align:left;"><strong>19.072 €</strong></td><td style="text-align:left;">Dollfuß-Museum-Vergangenheit, Abschiebungen nach Syrien/Afghanistan</td></tr><tr><td style="text-align:left;"><strong>Wolfgang Sobotka</strong></td><td style="text-align:left;">NR-Präs. a.D. / ÖVP-Akademie</td><td style="text-align:left;"><strong>Pension + X</strong></td><td style="text-align:left;">Mock-Institut, Novomatic-Verflechtung, „Goldenes Klavier“</td></tr></tbody></table><h2 id="tieferer-einblick-wolfgang-sobotka-–-architekt-der-macht" tabindex="-1">Tieferer Einblick: Wolfgang Sobotka – Architekt der Macht <a class="header-anchor" href="#tieferer-einblick-wolfgang-sobotka-–-architekt-der-macht" aria-label="Permalink to &quot;Tieferer Einblick: Wolfgang Sobotka – Architekt der Macht&quot;">​</a></h2><p>Wolfgang Sobotka ist die Symbolfigur für das System der „Harten Prosa“ im österreichischen Parlamentarismus. Auch nach seinem Rückzug aus der ersten Reihe (Oktober 2024) bleibt sein Einfluss spürbar:</p><ol><li><strong>Das Alois-Mock-Institut &amp; Novomatic:</strong> Als Präsident dieses Think-Tanks stand Sobotka im Zentrum von Vorwürfen über verdeckte Parteifinanzierung durch den Glücksspielkonzern Novomatic. Inserate und Sponsoring flossen reichlich, während Sobotka im Ibiza-U-Ausschuss den Vorsitz führte – eine klassische Konstellation der „Harten Prosa“.</li><li><strong>Das „Goldene Klavier“:</strong> Ein für 3.000 € monatlich gemieteter vergoldeter Bösendorfer-Flügel im Parlament wurde zum Symbol für die Abgehobenheit der Ära Sobotka während der Teuerungskrise. Es steht als Denkmal für die „Ästhetik der Kleinigkeit“ – auf Kosten der Steuerzahler.</li><li><strong>Der Rückzug ins Hinterzimmer (2025/26):</strong> Seit seinem Ausscheiden aus dem Nationalrat fungiert Sobotka als Präsident der Politischen Akademie der ÖVP. Hier sichert er die ideologische und strategische Kontinuität des Systems ab, finanziert durch Parteiförderungen und eine stattliche Politikerpension.</li></ol><h2 id="strategische-parallelen-zu-woginger-hattmannsdorfer" tabindex="-1">Strategische Parallelen zu Wöginger &amp; Hattmannsdorfer <a class="header-anchor" href="#strategische-parallelen-zu-woginger-hattmannsdorfer" aria-label="Permalink to &quot;Strategische Parallelen zu Wöginger &amp; Hattmannsdorfer&quot;">​</a></h2><p>Alle diese Figuren eint ein gemeinsames Muster:</p><ol><li><strong>Die Ochsentour:</strong> Aufstieg durch Bünde und Landesorganisationen.</li><li><strong>Die Posten-Architektur:</strong> Besetzung von Schlüsselstellen in Ministerien und staatsnahen Betrieben (Beispiel: Thomas Schmid).</li><li><strong>Die Nibelungentreue:</strong> Ein Rücktritt erfolgt erst im absoluten Notfall, davor wird jede Kritik als „Kriminalisierung der Politik“ abgetan.</li></ol><h2 id="forensisches-fazit" tabindex="-1">Forensisches Fazit <a class="header-anchor" href="#forensisches-fazit" aria-label="Permalink to &quot;Forensisches Fazit&quot;">​</a></h2><p>Während das Durchschnittsgehalt in Österreich stagniert, gönnt sich die Spitze der OÖVP (Stelzer) Gehaltserhöhungen, um eine „Selbstentwertung“ zu verhindern. Gleichzeitig wird der Druck auf Whistleblower wie <strong>Christa Scharf</strong> erhöht.</p><p>Das „Horten-Mysterium“ zeigt: Das Geld ist nie weg, es hat nur jemand anderes. Meistens jemand mit dem richtigen Parteibuch.</p>',14)])])}const f=t(a,[["render",s]]);export{c as __pageData,f as default};
